ALTER TABLE scholarships ADD COLUMN source_type VARCHAR(20) NOT NULL DEFAULT 'institution';
ALTER TABLE scholarships ADD COLUMN source_id VARCHAR(80);
ALTER TABLE scholarships ADD COLUMN source_url VARCHAR(2048);
ALTER TABLE scholarships ADD COLUMN application_url VARCHAR(2048);
ALTER TABLE scholarships ADD COLUMN opens_on DATE;
ALTER TABLE scholarships ADD COLUMN deadline_on DATE;
ALTER TABLE scholarships ADD COLUMN synced_at TIMESTAMP;
ALTER TABLE scholarships ADD COLUMN stale BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE scholarships SET source_type='legacy',status='closed' WHERE owner_id IS NULL;
CREATE INDEX scholarships_live_idx ON scholarships(source_type,status,deadline_on);
CREATE INDEX scholarships_source_idx ON scholarships(source_id);
CREATE TABLE scholarship_sources (id VARCHAR(80) PRIMARY KEY, name VARCHAR(200) NOT NULL, source_url VARCHAR(2048) NOT NULL, status VARCHAR(30) NOT NULL, message VARCHAR(1000) NOT NULL DEFAULT '', record_count INTEGER NOT NULL DEFAULT 0, last_attempt_at TIMESTAMP NOT NULL, last_success_at TIMESTAMP);
CREATE TABLE sync_leases (id VARCHAR(80) PRIMARY KEY, locked_until TIMESTAMP NOT NULL);
INSERT INTO sync_leases(id,locked_until) VALUES ('scholarships',TIMESTAMP '1970-01-01 00:00:00');
CREATE TABLE document_contents (document_id VARCHAR(36) PRIMARY KEY REFERENCES documents(id) ON DELETE CASCADE, content BYTEA NOT NULL);
CREATE TABLE spring_session (primary_id CHAR(36) NOT NULL PRIMARY KEY, session_id CHAR(36) NOT NULL, creation_time BIGINT NOT NULL, last_access_time BIGINT NOT NULL, max_inactive_interval INTEGER NOT NULL, expiry_time BIGINT NOT NULL, principal_name VARCHAR(100));
CREATE UNIQUE INDEX spring_session_id_idx ON spring_session(session_id);
CREATE INDEX spring_session_expiry_idx ON spring_session(expiry_time);
CREATE INDEX spring_session_principal_idx ON spring_session(principal_name);
CREATE TABLE spring_session_attributes (session_primary_id CHAR(36) NOT NULL REFERENCES spring_session(primary_id) ON DELETE CASCADE, attribute_name VARCHAR(200) NOT NULL, attribute_bytes BYTEA NOT NULL, PRIMARY KEY(session_primary_id,attribute_name));
